use std::fs::{self, ReadDir};
use std::io;
use std::path::Path;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

pub(crate) const LABELS: [&str; 6] = [
    "Projects & chats",
    "Analysis cache",
    "Generated files",
    "Agents",
    "Import backups",
    "Other",
];

pub(crate) const DESCRIPTIONS: [&str; 6] = [
    "Projects, chats, notes, function lists, saved native analysis and database logs.",
    "Cached code views. Clearing this cache keeps your saved work.",
    "Documents and decoded Android files generated by Prism.",
    "Agent downloads, their icons and the local registry.",
    "Safety copies made while importing from Prism.",
    "Engine files, settings, skills, recordings and other files in this folder.",
];

#[derive(Default)]
pub(crate) struct Usage {
    pub bytes: [u64; 6],
    pub incomplete: Option<String>,
}

impl Usage {
    pub fn total(&self) -> u64 {
        self.bytes.iter().sum()
    }

    fn issue(&mut self, message: impl Into<String>) {
        if self.incomplete.is_none() {
            self.incomplete = Some(message.into().chars().take(512).collect());
        }
    }
}

/// Measures logical file sizes without reading contents or following symbolic links.
pub(crate) fn measure(root: &Path, cancelled: &AtomicBool) -> io::Result<Usage> {
    let mut folders = vec![(fs::read_dir(root)?, None)];
    let mut usage = Usage::default();
    let started = Instant::now();
    let mut visited = 0;

    while !folders.is_empty() {
        if cancelled.load(Ordering::Relaxed) {
            return Err(io::Error::new(io::ErrorKind::Interrupted, "Scan cancelled"));
        }
        if visited >= 100_000 || started.elapsed() >= Duration::from_secs(10) {
            usage.issue("The scan reached its limit. Some local files have not been counted.");
            break;
        }

        let Some((entry, category)) = next_entry(&mut folders) else {
            continue;
        };
        visited += 1;
        match entry {
            Ok(entry) => count_entry(entry, category, &mut folders, &mut usage),
            Err(error) => usage.issue(format!("Some entries could not be read: {error}")),
        }
    }

    Ok(usage)
}

type Folder = (ReadDir, Option<usize>);

fn next_entry(folders: &mut Vec<Folder>) -> Option<(io::Result<fs::DirEntry>, Option<usize>)> {
    let (folder, category) = folders.last_mut()?;
    if let Some(entry) = folder.next() {
        Some((entry, *category))
    } else {
        folders.pop();
        None
    }
}

fn count_entry(
    entry: fs::DirEntry,
    category: Option<usize>,
    folders: &mut Vec<Folder>,
    usage: &mut Usage,
) {
    let result = (|| -> io::Result<()> {
        let kind = entry.file_type()?;
        let category = category.unwrap_or_else(|| category_for(&entry.file_name()));
        if kind.is_file() {
            // DirEntry metadata does not follow a symlink if the entry changes during a scan.
            let metadata = entry.metadata()?;
            if metadata.is_file() {
                let bytes = metadata.len();
                usage
                    .total()
                    .checked_add(bytes)
                    .ok_or_else(|| io::Error::other("File sizes exceed the supported range"))?;
                usage.bytes[category] += bytes;
            }
        } else if kind.is_dir() {
            if folders.len() >= 64 {
                return Err(io::Error::other("A folder is nested too deeply to measure"));
            }
            folders.push((fs::read_dir(entry.path())?, Some(category)));
        }
        Ok(())
    })();

    if let Err(error) = result {
        usage.issue(format!(
            "Could not measure {}: {error}",
            entry.path().display()
        ));
    }
}

fn category_for(name: &std::ffi::OsStr) -> usize {
    let Some(name) = name.to_str() else {
        return 5;
    };
    if name == "prism.db" || name.starts_with("prism.db-") {
        return 0;
    }
    if name == "prism.views.db" || name.starts_with("prism.views.db-") {
        return 1;
    }
    match name {
        "analysis-state" => 0,
        "documents" | "android" => 2,
        "agents" => 3,
        "imports" => 4,
        _ => 5,
    }
}

pub(crate) fn format_bytes(bytes: u64) -> String {
    let mut value = bytes as f64;
    let mut unit = "B";
    for next in ["KB", "MB", "GB", "TB", "PB", "EB"] {
        if value < 1000.0 {
            break;
        }
        value /= 1000.0;
        unit = next;
    }
    if bytes < 1000 {
        format!("{bytes} B")
    } else {
        format!("{value:.1} {unit}")
    }
}
